(async () => {
  const urls = [
    'https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v2/teams/1',
    'https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v1/competitions/8/seasons/2025/teamform',
    'https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v1/competitions/8/seasons/2025/teams/1/form',
    'https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v1/competitions/8/seasons/2025/teams/1/nextfixture',
    'https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v1/metadata/SDP_FOOTBALL_TEAM/1'
  ];

  const results = {};

  for (const url of urls) {
    try {
      const res = await fetch(url, { credentials: 'include' });
      const status = res.status;
      let json = null;
      let topLevelKeys = null;
      try {
        json = await res.json();
        if (json && typeof json === 'object') {
          topLevelKeys = Object.keys(json).slice(0, 10);
        }
      } catch (e) {
        json = { parseError: String(e) };
      }
      results[url] = { ok: true, status, topLevelKeys, error: null };
    } catch (e) {
      results[url] = { ok: false, status: null, topLevelKeys: null, error: String(e) };
    }
  }

  return results;
})()

